// Core error/severity types for the analyzer.
#ifndef ERRORTYPES_H
#define ERRORTYPES_H

#include <string>
#include <list>
#include <vector>

enum class Severity {
    none,
    error,
    warning,
    style,
    portability,
    performance,
    information,
    debug,
    internal
};

const char *toString(Severity s);
Severity severityFromString(const std::string &s);

enum class Certainty { normal, inconclusive };

// A single source location in a diagnostic.
struct FileLocation {
    FileLocation() = default;
    FileLocation(std::string f, int l, int c) : fileName(std::move(f)), line(l), column(c) {}
    FileLocation(std::string f, std::string i, int l, int c)
        : fileName(std::move(f)), mInfo(std::move(i)), line(l), column(c) {}

    std::string fileName;
    std::string mInfo;
    int line = 0;
    int column = 0;

    std::string getinfo() const { return mInfo; }
    void setinfo(const std::string &i) { mInfo = i; }
    // Path with separators normalised for output.
    std::string getFile() const;
};

class Settings;

// One diagnostic produced by a check (or by the framework).
class ErrorMessage {
public:
    ErrorMessage() = default;

    std::list<FileLocation> callStack;
    std::string id;
    Severity severity = Severity::none;
    std::string shortMessage;   // "msg"
    std::string verboseMessage; // "verbose"
    unsigned long long cwe = 0;
    Certainty certainty = Certainty::normal;
    std::string file0;
    std::string remark;
    std::string guideline;
    std::string classification;
    std::vector<std::string> symbolNames;
    bool internalError = false;

    void setmsg(const std::string &msg);

    std::string toString(bool verbose,
                         const std::string &templateFormat = std::string(),
                         const std::string &templateLocation = std::string()) const;
    std::string toXML() const;
    std::string serialize() const;

    std::string fixInvalidChars(const std::string &raw) const;
    unsigned int hash() const;
};

#endif

