#include "utils.h"

#include <algorithm>
#include <cctype>
#include <cstdlib>
#include <set>
#include <sstream>

namespace utils {

bool startsWith(const std::string &str, const std::string &prefix)
{
    return str.size() >= prefix.size() && str.compare(0, prefix.size(), prefix) == 0;
}

bool endsWith(const std::string &str, const std::string &suffix)
{
    return str.size() >= suffix.size() &&
           str.compare(str.size() - suffix.size(), suffix.size(), suffix) == 0;
}

std::string trim(const std::string &s, const std::string &chars)
{
    const std::string::size_type b = s.find_first_not_of(chars);
    if (b == std::string::npos)
        return "";
    const std::string::size_type e = s.find_last_not_of(chars);
    return s.substr(b, e - b + 1);
}

std::vector<std::string> split(const std::string &s, char sep)
{
    std::vector<std::string> ret;
    std::string::size_type pos = 0;
    while (true) {
        const std::string::size_type next = s.find(sep, pos);
        if (next == std::string::npos) {
            ret.push_back(s.substr(pos));
            break;
        }
        ret.push_back(s.substr(pos, next - pos));
        pos = next + 1;
    }
    return ret;
}

std::vector<std::string> splitAny(const std::string &s, const std::string &seps)
{
    std::vector<std::string> ret;
    std::string cur;
    for (const char c : s) {
        if (seps.find(c) != std::string::npos) {
            ret.push_back(cur);
            cur.clear();
        } else
            cur += c;
    }
    ret.push_back(cur);
    return ret;
}

std::string join(const std::vector<std::string> &v, const std::string &sep)
{
    std::string ret;
    for (std::size_t i = 0; i < v.size(); ++i) {
        if (i)
            ret += sep;
        ret += v[i];
    }
    return ret;
}

std::string replaceAll(std::string s, const std::string &from, const std::string &to)
{
    if (from.empty())
        return s;
    std::string::size_type pos = 0;
    while ((pos = s.find(from, pos)) != std::string::npos) {
        s.replace(pos, from.size(), to);
        pos += to.size();
    }
    return s;
}

std::string toLower(std::string s)
{
    std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c) {
        return static_cast<char>(std::tolower(c));
    });
    return s;
}

std::string toUpper(std::string s)
{
    std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c) {
        return static_cast<char>(std::toupper(c));
    });
    return s;
}

bool strToInt(const std::string &s, long long &result)
{
    if (s.empty())
        return false;
    std::size_t i = 0;
    bool neg = false;
    if (s[0] == '+' || s[0] == '-') {
        neg = (s[0] == '-');
        i = 1;
    }
    if (i >= s.size())
        return false;
    unsigned long long v = 0;
    for (; i < s.size(); ++i) {
        if (!std::isdigit(static_cast<unsigned char>(s[i])))
            return false;
        const unsigned long long nv = v * 10 + static_cast<unsigned>(s[i] - '0');
        if (nv < v)
            return false;
        v = nv;
    }
    result = neg ? -static_cast<long long>(v) : static_cast<long long>(v);
    return true;
}

bool strToInt(const std::string &s, int &result)
{
    long long v;
    if (!strToInt(s, v))
        return false;
    result = static_cast<int>(v);
    return true;
}

bool parseIntLiteral(const std::string &s, long long &result)
{
    if (s.empty())
        return false;
    std::string body = s;
    // strip integer suffixes
    while (!body.empty()) {
        const char c = body.back();
        if (c == 'u' || c == 'U' || c == 'l' || c == 'L')
            body.pop_back();
        else
            break;
    }
    if (body.empty())
        return false;
    // strip digit separators
    body = replaceAll(body, "'", "");
    errno = 0;
    char *end = nullptr;
    unsigned long long v;
    if (body.size() > 2 && body[0] == '0' && (body[1] == 'b' || body[1] == 'B'))
        v = std::strtoull(body.c_str() + 2, &end, 2);
    else
        v = std::strtoull(body.c_str(), &end, 0);
    if (end == nullptr || *end != '\0')
        return false;
    result = static_cast<long long>(v);
    return true;
}

bool isIntLiteral(const std::string &s)
{
    if (s.empty() || !std::isdigit(static_cast<unsigned char>(s[0])))
        return false;
    return s.find('.') == std::string::npos &&
           !(s.find('e') != std::string::npos && s.compare(0, 2, "0x") != 0 && s.compare(0, 2, "0X") != 0) &&
           !(s.find('E') != std::string::npos && s.compare(0, 2, "0x") != 0 && s.compare(0, 2, "0X") != 0) &&
           s.find('p') == std::string::npos && s.find('P') == std::string::npos;
}

bool isFloatLiteral(const std::string &s)
{
    if (s.empty())
        return false;
    if (!std::isdigit(static_cast<unsigned char>(s[0])) && s[0] != '.')
        return false;
    return !isIntLiteral(s);
}

bool isStringLiteral(const std::string &s)
{
    if (s.size() < 2)
        return false;
    if (s.back() != '"')
        return false;
    const std::string::size_type q = s.find('"');
    return q != std::string::npos && q + 1 <= s.size() - 1;
}

bool isCharLiteral(const std::string &s)
{
    if (s.size() < 3)
        return false;
    if (s.back() != '\'')
        return false;
    const std::string::size_type q = s.find('\'');
    return q != std::string::npos && q < s.size() - 1;
}

bool isNameChar(char c)
{
    return std::isalnum(static_cast<unsigned char>(c)) || c == '_' || c == '$' ||
           static_cast<unsigned char>(c) >= 0x80;
}

bool isName(const std::string &s)
{
    if (s.empty())
        return false;
    if (std::isdigit(static_cast<unsigned char>(s[0])))
        return false;
    for (const char c : s) {
        if (!isNameChar(c))
            return false;
    }
    return true;
}

static const std::set<std::string> &keywordSet()
{
    static const std::set<std::string> kw = {
        "alignas", "alignof", "and", "and_eq", "asm", "auto", "bitand", "bitor", "bool", "break",
        "case", "catch", "char", "char16_t", "char32_t", "char8_t", "class", "co_await",
        "co_return", "co_yield", "compl", "concept", "const", "const_cast", "consteval",
        "constexpr", "constinit", "continue", "decltype", "default", "delete", "do", "double",
        "dynamic_cast", "else", "enum", "explicit", "export", "extern", "false", "float", "for",
        "friend", "goto", "if", "inline", "int", "long", "mutable", "namespace", "new", "noexcept",
        "not", "not_eq", "nullptr", "operator", "or", "or_eq", "private", "protected", "public",
        "register", "reinterpret_cast", "requires", "return", "short", "signed", "sizeof",
        "static", "static_assert", "static_cast", "struct", "switch", "template", "this",
        "thread_local", "throw", "true", "try", "typedef", "typeid", "typename", "union",
        "unsigned", "using", "virtual", "void", "volatile", "wchar_t", "while", "xor", "xor_eq",
        "_Bool", "restrict", "_Atomic", "_Generic", "_Noreturn", "_Static_assert"
    };
    return kw;
}

bool isKeyword(const std::string &s)
{
    return keywordSet().count(s) > 0;
}

// Glob matcher supporting '?', '*' (not crossing '/') and '**' (crossing '/').
static bool globHelper(const char *p, const char *t)
{
    while (*p) {
        if (*p == '*') {
            const bool dbl = (p[1] == '*');
            const char *pn = p + (dbl ? 2 : 1);
            if (dbl) {
                // '**' matches anything including separators
                for (const char *tt = t;; ++tt) {
                    if (globHelper(pn, tt))
                        return true;
                    if (!*tt)
                        return false;
                }
            }
            for (const char *tt = t;; ++tt) {
                if (globHelper(pn, tt))
                    return true;
                if (!*tt || *tt == '/')
                    return false;
            }
        }
        if (!*t)
            return false;
        if (*p == '?') {
            if (*t == '/')
                return false;
        } else if (*p != *t)
            return false;
        ++p;
        ++t;
    }
    return *t == '\0';
}

bool matchGlob(const std::string &pattern, const std::string &text)
{
    return globHelper(pattern.c_str(), text.c_str());
}

std::string xmlEncode(const std::string &s)
{
    std::string ret;
    ret.reserve(s.size());
    for (const char c : s) {
        switch (c) {
        case '&':  ret += "&amp;"; break;
        case '<':  ret += "&lt;"; break;
        case '>':  ret += "&gt;"; break;
        case '"':  ret += "&quot;"; break;
        case '\'': ret += "&apos;"; break;
        default:
            if (static_cast<unsigned char>(c) < 0x20 && c != '\t' && c != '\n' && c != '\r')
                break;
            ret += c;
        }
    }
    return ret;
}

std::string jsonEncode(const std::string &s)
{
    std::string ret;
    for (const char c : s) {
        switch (c) {
        case '"':  ret += "\\\""; break;
        case '\\': ret += "\\\\"; break;
        case '\b': ret += "\\b"; break;
        case '\f': ret += "\\f"; break;
        case '\n': ret += "\\n"; break;
        case '\r': ret += "\\r"; break;
        case '\t': ret += "\\t"; break;
        default:
            if (static_cast<unsigned char>(c) < 0x20) {
                char buf[8];
                std::snprintf(buf, sizeof(buf), "\\u%04x", static_cast<unsigned>(c));
                ret += buf;
            } else
                ret += c;
        }
    }
    return ret;
}

std::string decodeTemplateEscapes(const std::string &s)
{
    std::string ret;
    for (std::size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '\\' && i + 1 < s.size()) {
            switch (s[i + 1]) {
            case 'n': ret += '\n'; ++i; continue;
            case 't': ret += '\t'; ++i; continue;
            case 'r': ret += '\r'; ++i; continue;
            case '\\': ret += '\\'; ++i; continue;
            default: break;
            }
        }
        ret += s[i];
    }
    return ret;
}

std::string trimTrailingNewlines(std::string s)
{
    while (!s.empty() && (s.back() == '\n' || s.back() == '\r'))
        s.pop_back();
    return s;
}

} // namespace utils

