           str.compare(str.size() - suffix.size(), suffix.size(), suffix) == 0;
}

std::string trim(const std::string &s, const std::string &chars)
{
    const std::string::size_type b = s.find_first_not_of(chars);
    if (b == std::string::npos)
        return "";
    const std::string::size_type e = s.find_last_not_of(chars);
    return s.substr(b, e - b + 1);
}

std::vector<std::string> split(const std::string &s, char sep)
{
    std::vector<std::string> ret;
    std::string::size_type pos = 0;
    while (true) {
        const std::string::size_type next = s.find(sep, pos);
        if (next == std::string::npos) {
            ret.push_back(s.substr(pos));
            break;
        }
        ret.push_back(s.substr(pos, next - pos));
        pos = next + 1;
    }
    return ret;
}

std::vector<std::string> splitAny(const std::string &s, const std::string &seps)
{
    std::vector<std::string> ret;
    std::string cur;
    for (const char c : s) {
        if (seps.find(c) != std::string::npos) {
            ret.push_back(cur);
            cur.clear();
        } else
            cur += c;
    }
    ret.push_back(cur);
    return ret;
}

std::string join(const std::vector<std::string> &v, const std::string &sep)
{
    std::string ret;
    for (std::size_t i = 0; i < v.size(); ++i) {
        if (i)
            ret += sep;
        ret += v[i];
    }
    return ret;
}

std::string replaceAll(std::string s, const std::string &from, const std::string &to)
{
    if (from.empty())
        return s;
    std::string::size_type pos = 0;
    while ((pos = s.find(from, pos)) != std::string::npos) {
        s.replace(pos, from.size(), to);
        pos += to.size();
    }
    return s;
}

std::string toLower(std::string s)
{
    std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c) {
        return static_cast<char>(std::tolower(c));
    });
    return s;
}

std::string toUpper(std::string s)
{
    std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c) {
        return static_cast<char>(std::toupper(c));
    });
    return s;
}

bool strToInt(const std::string &s, long long &result)
{
    if (s.empty())
        return false;
    std::size_t i = 0;
    bool neg = false;
    if (s[0] == '+' || s[0] == '-') {
        neg = (s[0] == '-');
        i = 1;
    }
    if (i >= s.size())
        return false;
    unsigned long long v = 0;
    for (; i < s.size(); ++i) {
        if (!std::isdigit(static_cast<unsigned char>(s[i])))
            return false;
        const unsigned long long nv = v * 10 + static_cast<unsigned>(s[i] - '0');
        if (nv < v)
            return false;
        v = nv;
    }
    result = neg ? -static_cast<long long>(v) : static_cast<long long>(v);
    return true;
}

bool strToInt(const std::string &s, int &result)
{
    long long v;
    if (!strToInt(s, v))
        return false;
    result = static_cast<int>(v);
    return true;
}

bool parseIntLiteral(const std::string &s, long long &result)
{
    if (s.empty())
        return false;
    std::string body = s;
    // strip integer suffixes
    while (!body.empty()) {
        const char c = body.back();
        if (c == 'u' || c == 'U' || c == 'l' || c == 'L')
            body.pop_back();
        else
            break;
    }
    if (body.empty())
        return false;
    // strip digit separators
    body = replaceAll(body, "'", "");
    errno = 0;
    char *end = nullptr;
    unsigned long long v;
    if (body.size() > 2 && body[0] == '0' && (body[1] == 'b' || body[1] == 'B'))
        v = std::strtoull(body.c_str() + 2, &end, 2);
    else
        v = std::strtoull(body.c_str(), &end, 0);
    if (end == nullptr || *end != '\0')
        return false;
    result = static_cast<long long>(v);
    return true;
}

bool isIntLiteral(const std::string &s)
{
    if (s.empty() || !std::isdigit(static_cast<unsigned char>(s[0])))
        return false;
    return s.find('.') == std::string::npos &&
           !(s.find('e') != std::string::npos && s.compare(0, 2, "0x") != 0 && s.compare(0, 2, "0X") != 0) &&
           !(s.find('E') != std::string::npos && s.compare(0, 2, "0x") != 0 && s.compare(0, 2, "0X") != 0) &&
           s.find('p') == std::string::npos && s.find('P') == std::string::npos;
}

bool isFloatLiteral(const std::string &s)
{
    if (s.empty())
        return false;
    if (!std::isdigit(static_cast<unsigned char>(s[0])) && s[0] != '.')
        return false;
    return !isIntLiteral(s);
}

bool isStringLiteral(const std::string &s)
{
    if (s.size() < 2)
        return false;
    if (s.back() != '"')
        return false;
    const std::string::size_type q = s.find('"');
    return q != std::string::npos && q + 1 <= s.size() - 1;
}

bool isCharLiteral(const std::string &s)
{
    if (s.size() < 3)
        return false;
    if (s.back() != '\'')
        return false;
    const std::string::size_type q = s.find('\'');
    return q != std::string::npos && q < s.size() - 1;
}

bool isNameChar(char c)
{
    return std::isalnum(static_cast<unsigned char>(c)) || c == '_' || c == '$' ||
           static_cast<unsigned char>(c) >= 0x80;
}

bool isName(const std::string &s)
{
    if (s.empty())
        return false;
    if (std::isdigit(static_cast<unsigned char>(s[0])))
        return false;
    for (const char c : s) {
        if (!isNameChar(c))
            return false;
    }
    return true;
}

